/**
 * Nakshatra -> Pada -> Swar table.
 * Source: Drik Panchang "Nakshatra Pada Swar Siddhanta" table (27 x 4 = 108).
 * `drik` is the Swar exactly as Drik Panchang prints it.
 *
 * `variants` = what the numerologist sends to customers ("Nee, Ni, N").
 * Only the entries listed in CONFIRMED_VARIANTS are verified from real client
 * orders. Every other entry is generated by `buildVariants()` and must be
 * reviewed once by the client (see `isConfirmed()`); the admin screen lets the
 * operator edit the list before sending, so a wrong guess never reaches a customer silently.
 */

export const NAKSHATRAS = [
  "Ashwini", "Bharani", "Krittika", "Rohini", "Mrigashira", "Ardra",
  "Punarvasu", "Pushya", "Ashlesha", "Magha", "Purva Phalguni", "Uttara Phalguni",
  "Hasta", "Chitra", "Swati", "Vishakha", "Anuradha", "Jyeshtha",
  "Mula", "Purva Ashadha", "Uttara Ashadha", "Shravana", "Dhanishtha", "Shatabhisha",
  "Purva Bhadrapada", "Uttara Bhadrapada", "Revati",
] as const;

/** DRIK_SWAR[nakshatraIndex][padaIndex] */
export const DRIK_SWAR: string[][] = [
  ["Chu", "Che", "Cho", "Laa"],      // 1 Ashwini
  ["Lee", "Loo", "Le", "Lo"],        // 2 Bharani
  ["A", "Ee", "U", "E"],             // 3 Krittika
  ["O", "Vaa", "Vee", "Vu"],         // 4 Rohini
  ["Ve", "Vo", "Kaa", "Kee"],        // 5 Mrigashira
  ["Ku", "Gha", "Ing", "Chha"],      // 6 Ardra
  ["Ke", "Ko", "Haa", "Hee"],        // 7 Punarvasu
  ["Hu", "He", "Ho", "Daa"],         // 8 Pushya
  ["Dee", "Doo", "De", "Do"],        // 9 Ashlesha
  ["Maa", "Mee", "Moo", "Me"],       // 10 Magha
  ["Mo", "Taa", "Tee", "Too"],       // 11 Purva Phalguni
  ["Te", "To", "Paa", "Pee"],        // 12 Uttara Phalguni
  ["Poo", "Sha", "Na", "Tha"],       // 13 Hasta
  ["Pe", "Po", "Raa", "Ree"],        // 14 Chitra
  ["Roo", "Re", "Ro", "Taa"],        // 15 Swati
  ["Tee", "Too", "Te", "To"],        // 16 Vishakha
  ["Naa", "Nee", "Noo", "Ne"],       // 17 Anuradha
  ["No", "Yaa", "Yee", "Yoo"],       // 18 Jyeshtha
  ["Ye", "Yo", "Bhaa", "Bhee"],      // 19 Mula
  ["Bhoo", "Dhaa", "Phaa", "Dha"],   // 20 Purva Ashadha
  ["Bhe", "Bho", "Jaa", "Jee"],      // 21 Uttara Ashadha
  ["Khee", "Khoo", "Khe", "Kho"],    // 22 Shravana
  ["Gaa", "Gee", "Gu", "Ge"],        // 23 Dhanishtha
  ["Go", "Saa", "See", "Soo"],       // 24 Shatabhisha
  ["Se", "So", "Daa", "Dee"],        // 25 Purva Bhadrapada
  ["Doo", "Tha", "Jha", "Yna"],      // 26 Uttara Bhadrapada
  ["De", "Do", "Cha", "Chee"],       // 27 Revati
];

/** Verified from real client orders ("nakshatraIndex-pada" -> list sent to customers). */
export const CONFIRMED_VARIANTS: Record<string, string[]> = {
  "17-2": ["Nee", "Ni", "N"],                    // Anuradha 2
  "24-3": ["See", "Si", "Shee", "Shi", "S"],     // Shatabhisha 3
  "21-3": ["Jaa", "Ja", "J"],                    // Uttara Ashadha 3
  "15-1": ["Roo", "Ru", "R"],                    // Swati 1
  "6-1": ["Ku", "Koo", "K"],                     // Ardra 1
  "1-4": ["Laa", "La", "L"],                     // Ashwini 4
};

/** Short <-> long vowel partner, following the pattern seen in confirmed orders. */
function altSpelling(s: string): string | null {
  if (/aa$/i.test(s)) return s.slice(0, -2) + "a";
  if (/ee$/i.test(s)) return s.slice(0, -2) + "i";
  if (/oo$/i.test(s)) return s.slice(0, -2) + "u";
  if (/u$/i.test(s)) return s.slice(0, -1) + "oo";
  if (/i$/i.test(s)) return s.slice(0, -1) + "ee";
  return null;
}

export function buildVariants(drik: string): string[] {
  const out = [drik];
  const alt = altSpelling(drik);
  if (alt && !out.includes(alt)) out.push(alt);
  const first = drik[0].toUpperCase();
  if (!out.includes(first)) out.push(first);
  return out;
}

export interface SwarEntry {
  nakshatra: string;
  nakshatraNo: number; // 1..27
  pada: number; // 1..4
  drik: string;
  variants: string[];
  /** true only if the variants list was verified from a real client order */
  confirmed: boolean;
  startLetter: string; // first letter of the Drik Swar, upper-case
}

export function getSwar(nakshatraNo: number, pada: number): SwarEntry {
  const drik = DRIK_SWAR[nakshatraNo - 1][pada - 1];
  const key = `${nakshatraNo}-${pada}`;
  const confirmedList = CONFIRMED_VARIANTS[key];
  return {
    nakshatra: NAKSHATRAS[nakshatraNo - 1],
    nakshatraNo,
    pada,
    drik,
    variants: confirmedList ?? buildVariants(drik),
    confirmed: Boolean(confirmedList),
    startLetter: drik[0].toUpperCase(),
  };
}

/** All four Pada Swar of a Nakshatra (for the "show all 4 padas" format). */
export function getAllPadaSwar(nakshatraNo: number): string[] {
  return DRIK_SWAR[nakshatraNo - 1];
}
